export function parseConfig(text) {
  const output = {};
  for (const rawLine of text.split(/\r?\n/u)) {
    let quote = null;
    let visible = "";
    for (const character of rawLine) {
      if ((character === "'" || character === '"') && (quote === null || quote === character)) quote = quote === null ? character : null;
      if (character === "#" && quote === null) break;
      visible += character;
    }
    const line = visible.trim();
    if (line === "") continue;
    const separator = line.indexOf("=");
    if (separator < 1) throw new SyntaxError(`invalid config line: ${rawLine}`);
    const key = line.slice(0, separator).trim();
    const rawValue = line.slice(separator + 1).trim();
    const quoted = (rawValue.startsWith('\"') && rawValue.endsWith('\"')) || (rawValue.startsWith("'") && rawValue.endsWith("'"));
    output[key] = quoted ? rawValue.slice(1, -1) : rawValue;
  }
  return output;
}
